def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Fast counters over relevant windows
    opp_c = op.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c

    last_my = me[-1]
    last_opp = op[-1]

    # Consecutive defections by opponent at the end
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_d += 1
        else:
            break

    # Consecutive cooperation by opponent at the end
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_c += 1
        else:
            break

    # Opponent cooperation rate overall and in recent window
    opp_rate = opp_c / n
    w = min(10, n)
    recent = op[-w:]
    recent_c = recent.count('C')
    recent_rate = recent_c / w

    # Strongly cooperative opponent: keep cooperating, only rare probing late
    if opp_d == 0:
        if n >= 96 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Pure defector: punish almost always
    if opp_c == 0:
        return 'D'

    # Very defection-heavy opponent
    if opp_rate < 0.15:
        # Occasional olive branch, especially if our last move was C
        if last_my == 'C' and consec_d < 4 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Very cooperative opponent: cooperate, with controlled endgame probing
    if opp_rate > 0.9:
        if n >= 95:
            # Defect more often near the end, but avoid ruining a strong CC run
            if consec_c >= 3 or rng.random() < 0.55:
                return 'D'
        return 'C'

    # Detect an always/strongly retaliatory tit-for-tat that mirrors our last action.
    mirror_hits = 0
    mirror_total = 0
    for i in range(1, n):
        if op[i] == me[i - 1]:
            mirror_hits += 1
        mirror_total += 1
    if n >= 5 and mirror_total > 0 and mirror_hits / mirror_total > 0.72:
        # Cooperating against a mirroring opponent locks in CC, which is optimal
        # under this payoff structure against TFT-like strategies.
        if n >= 98:
            # Last two rounds: if opponent is pure TFT, defecting once gets 5
            # then they retaliate. Evaluate payoff over last two rounds worst-case:
            # CC=3 then D? If we defect now and they mirror, next round DD=1.
            # Two-round totals: CC+CC=6 vs DC+DD=6, so DD path is safe, but if
            # they forgive, DC+CC=8. Pure TFT is more common, so late defection
            # is only worth it if we already have enough cushion or are behind.
            pass
        return 'C'

    # Opponent defected last round
    if last_opp == 'D':
        # If our previous move was also D, we are in a defection cycle; try to escape
        if last_my == 'D':
            if consec_d >= 3:
                # Long defection run: mostly defect, but occasionally attempt reset
                if rng.random() < 0.18:
                    return 'C'
                return 'D'
            if consec_d == 2:
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            # Single mutual defection: attempt to restore cooperation
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        else:
            # We cooperated, they defected: retaliation with forgiveness tuning
            if consec_d >= 4:
                if rng.random() < 0.12:
                    return 'C'
                return 'D'
            if consec_d >= 2:
                if recent_rate > 0.5 and rng.random() < 0.45:
                    return 'C'
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            # Single defection: retaliate usually, forgive sometimes to avoid traps
            if recent_rate > 0.6 and rng.random() < 0.4:
                return 'C'
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    # Opponent cooperated last round
    if last_opp == 'C':
        if last_my == 'D':
            # We retaliated; return to cooperation to rebuild
            return 'C'
        # Both cooperated
        if opp_rate > 0.6:
            # Mostly cooperative: defect only for calibrated endgame
            if n >= 96 and consec_c >= 2:
                if rng.random() < 0.55:
                    return 'D'
            # Rare probe to gather info, but avoid destabilizing strong cooperation
            if n < 90 and opp_rate > 0.8 and n % 23 == 0 and rng.random() < 0.25:
                return 'D'
            return 'C'
        else:
            # Mixed opponent cooperating now: exploit occasionally
            if rng.random() < 0.22:
                return 'D'
            return 'C'

    return 'C'
